import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import {
  ConversationEventType,
  UtteranceType,
  type Conversation,
  type ConversationEvent,
  type Skill,
  type Utterance,
} from "../../types";
import { EventInfo } from "./EventInfo";
import { SkillEventInfo, type SkillLifecycleEvent } from "./SkillEventInfo";

function userUtterance(text: string, originalTimestamp: number): Utterance {
  return {
    __typename: "Utterance",
    id: `u-${originalTimestamp}`,
    metadata: { parseData: {} },
    rephrase: false,
    rephrasePrompt: null,
    text,
    timestamp: new Date(originalTimestamp * 1000).toISOString(),
    tokens: [],
    type: UtteranceType.User,
    originalTimestamp,
  };
}

function conversationWith(...events: Conversation["events"]): Conversation[] {
  return [{ id: "c1", events } as Conversation];
}

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const cardReplace: Skill = {
  id: "card_replace",
  name: "Card replacement",
  description: "Replace a credit card — lost, stolen, damaged, or not received.",
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {},
  referenced_skills: ["card_faq"],
  tool_names: ["lock_card"],
  hidden: false,
};

function activationEvent(id: string): SkillLifecycleEvent {
  return {
    id,
    conversationEventType: ConversationEventType.SkillActivated,
    name: "skill_activated",
    actionText: "",
    skillId: "card_replace",
    stepId: "",
    slotValue: null,
    timestamp: "2020-01-01T00:00:00.000Z",
    originalTimestamp: 100,
    metadata: { parseData: {} },
    __typename: "ConversationEvent",
  };
}

describe("SkillEventInfo", () => {
  it("is selected for a known skill lifecycle event", () => {
    renderWithProviders(
      <EventInfo event={activationEvent("e1")} onClose={() => undefined} flows={[]} />,
      { initialStoreState: { skillCatalog: { card_replace: cardReplace } } },
    );

    expect(screen.getByRole("heading", { name: "Skill activated" })).toBeInTheDocument();
    expect(screen.getByText("card_replace")).toBeInTheDocument();
    expect(screen.getByText("Card replacement")).toBeInTheDocument();
  });

  it("keeps the skill panel when the catalog has not loaded yet", () => {
    renderWithProviders(
      <EventInfo event={activationEvent("e1")} onClose={() => undefined} flows={[]} />,
      { initialStoreState: { skillCatalog: null } },
    );

    expect(screen.getByRole("heading", { name: "Skill activated" })).toBeInTheDocument();
    expect(screen.getByText("card_replace")).toBeInTheDocument();
    expect(screen.queryByRole("heading", { name: "Event" })).toBeNull();
    expect(screen.queryByText("Card replacement")).toBeNull();
    expect(screen.queryByTestId("skill-event-tools")).toBeNull();
  });

  it("keeps the skill panel when the current catalog no longer has that id", () => {
    renderWithProviders(
      <EventInfo
        event={{ ...activationEvent("e1"), skillId: "deleted_skill" }}
        onClose={() => undefined}
        flows={[]}
      />,
      { initialStoreState: { skillCatalog: { card_replace: cardReplace } } },
    );

    expect(screen.getByRole("heading", { name: "Skill activated" })).toBeInTheDocument();
    expect(screen.getByText("deleted_skill")).toBeInTheDocument();
    expect(screen.queryByText("Card replacement")).toBeNull();
    expect(screen.queryByRole("heading", { name: "Event" })).toBeNull();
    expect(screen.queryByTestId("skill-event-tools")).toBeNull();
    expect(screen.queryByTestId("skill-event-references")).toBeNull();
  });

  it("shows the skill card with tools, references and the resolved trigger message", () => {
    const event: SkillLifecycleEvent = {
      ...activationEvent("e1"),
      metadata: { parseData: {}, triggering_user_message_timestamp: 42 },
    };
    renderWithProviders(<SkillEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: {
        skillCatalog: { card_replace: cardReplace },
        conversationList: conversationWith(userUtterance("My card was stolen", 42)),
      },
    });

    expect(screen.getByRole("heading", { name: "Skill activated" })).toBeInTheDocument();
    expect(screen.getByText("Card replacement")).toBeInTheDocument();
    expect(screen.getByText(/Replace a credit card/)).toBeInTheDocument();
    expect(screen.getByTestId("skill-event-tools")).toHaveTextContent("lock_card");
    expect(screen.getByTestId("skill-event-references")).toHaveTextContent("card_faq");
    expect(screen.getByTestId("skill-event-trigger")).toHaveTextContent("My card was stolen");
  });

  it("omits the trigger when the stamped timestamp matches no user utterance", () => {
    const event: SkillLifecycleEvent = {
      ...activationEvent("e1"),
      metadata: { parseData: {}, triggering_user_message_timestamp: 999 },
    };
    renderWithProviders(<SkillEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: {
        skillCatalog: { card_replace: cardReplace },
        conversationList: conversationWith(userUtterance("Unrelated message", 42)),
      },
    });
    expect(screen.queryByTestId("skill-event-trigger")).toBeNull();
  });

  it("omits the trigger block without a stamped timestamp", () => {
    const event = activationEvent("e1");
    renderWithProviders(<SkillEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: {
        skillCatalog: { card_replace: cardReplace },
      },
    });
    expect(screen.queryByTestId("skill-event-trigger")).toBeNull();
  });

  it("shows the step id when the lifecycle event carries one", () => {
    const event: SkillLifecycleEvent = {
      ...activationEvent("e1"),
      conversationEventType: ConversationEventType.SkillInterrupted,
      stepId: "confirm_replacement",
    };
    renderWithProviders(<SkillEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: {
        skillCatalog: { card_replace: cardReplace },
      },
    });

    expect(screen.getByText("confirm_replacement")).toBeInTheDocument();
  });
});

describe("EventInfo skill-event routing", () => {
  it("does not use the skill panel when a Skill* event has no skill id", () => {
    const event: ConversationEvent = {
      ...activationEvent("e1"),
      skillId: undefined,
    };
    renderWithProviders(<EventInfo event={event} onClose={() => undefined} flows={[]} />, {
      initialStoreState: { skillCatalog: { card_replace: cardReplace } },
    });

    expect(screen.queryByRole("heading", { name: "Skill activated" })).toBeNull();
    expect(screen.getByRole("heading", { name: "Event" })).toBeInTheDocument();
  });
});
